"""Instance generation for every family generated by its recipe (src.utils.families), in the paper's artifact format.

For each (size, seed) the instance folder <out_root>/<problem>_<size>_seed<seed:03d> gets data.json and the generator's
sidecar (source.json or provenance.json: recipe provenance, never part of data.json or the prompt), prompt.txt rendered
with the family's dataset contract (src.agent.prompts.snapshot.render_case_prompt, the same text a campaign init
renders), gold_monolithic.json, gold_<suite>.json and, once admitted, meta.json. Stale files of an earlier generation
are removed first, so an instance that is not admitted is left without meta.json and is never complete.

The admission rule ("strict", every family generated with the current recipes). An instance is admitted only if
  1. generation and prompt rendering succeed;
  2. the monolithic MIP (MIP_PARAMS: Threads = 1, MIPGap = 0, TimeLimit = the family's mip_time_limit, 1800 s) proves
     optimality (its wrapper raises otherwise), its plan passes the harness verifier, its reported solve time
     (total_time or runtime, when the wrapper reports one) is within the limit and its bounds are closed
     (|ub - lb| <= 1e-9 max(1, |z|));
  3. the decomposition reference (time_limit = REFERENCE_TIME_LIMIT = 60 s, plus the family's reference_options)
     returns a verified plan within 0 <= total_time <= 60 s;
  4. its relative gap (z_ref - z_mip) / max(1, |z_mip|) lies in [-tol, GAP_RULE = 1 %] (a reference materially below a
     proved optimum is an inconsistency);
  5. a reference that certifies its own optimality (global bounds meeting its objective within tol) matches the MIP
     optimum within tol, and a family with reference_certified = True must have that certificate.
A rejected instance raises RuntimeError and gets a rejection.json with the reason; no seed is ever replaced or skipped.
The ground truth is the proved MIP optimum.

The reused instances of lbbd, gcol and nrp keep their historical rule ("mip_or_certificate", configs/harder_small_all.json):
MIP TimeLimit 300 s (family defaults otherwise), reference time limit 60 s, both plans verified, a certified reference
must match the MIP optimum, and the ground truth is the MIP optimum or else the reference certificate; an instance
with neither gets no meta.json and is skipped.

meta.json keeps the layout of each family's existing dataset (META_LAYOUTS): "instance_info" (ufl, km, fctp),
"recipe_fields" (bp, csp, gap, bppc; the golds also record wall_seconds) and "source_summary" (all others).
"""
from __future__ import annotations

import importlib
import json
import math
from pathlib import Path
import time
from typing import Any, Callable

from src.utils.api import solve, verify
from src.utils.families import Family, family


MIP_PARAMS = {"Threads": 1, "MIPGap": 0.0}
REFERENCE_TIME_LIMIT = 60.0
GAP_RULE = 0.01
MIP_BOUND_TOL = 1e-9
SIDECARS = ("source.json", "provenance.json")
MIP_SECONDS_DEFINITION = "wall time of the Gurobi optimize() call (BaseBaseline total_time)"


def certified(result: dict[str, Any] | None, tol: float = 1e-6) -> bool:
    """Finite, ordered bounds that meet, and an upper bound equal to the reported (verified) objective."""
    if not result:
        return False
    lb, ub, obj = result.get("global_lb"), result.get("global_ub"), result.get("best_objective")
    if any(not isinstance(v, (int, float)) or not math.isfinite(v) for v in (lb, ub, obj)):
        return False
    scale = tol * max(1.0, abs(ub))
    return lb <= ub + scale and ub - lb <= scale and abs(ub - obj) <= scale


def _write(path: Path, payload: dict[str, Any]) -> None:
    path.write_text(json.dumps(payload, indent=2, default=str))


def _generator(entry: Family) -> Callable:
    module = importlib.import_module(f"{entry.module}.a_gen_data")
    gen = getattr(module, entry.generator)
    recipe = getattr(module, entry.recipe) if entry.recipe else None

    def run(seed: int, size: str, inst_dir: Path):
        result = gen(seed, size, inst_dir)
        return result if recipe is None else (result, recipe(seed, size))
    return run


def _render(entry: Family, contract: str | None) -> Callable[[dict], str]:
    from src.agent.prompts.snapshot import render_case_prompt
    return lambda data: render_case_prompt(entry.suite, entry.name, data, contract or entry.contract)


def _sidecar(inst_dir: Path) -> tuple[str, dict] | None:
    for name in SIDECARS:
        if (inst_dir / name).is_file():
            return name, json.loads((inst_dir / name).read_text())
    return None


def _references(entry: Family, path: Path, *, strict: bool) -> dict[str, dict[str, Any]]:
    """Both golds as written to disk; the MIP wrappers raise unless Gurobi proves optimality."""
    params = {**MIP_PARAMS, "TimeLimit": entry.mip_time_limit} if strict else {"TimeLimit": entry.mip_time_limit}
    results = {}
    for method, options in (("monolithic", {"params": params}),
                            ("decomposition", {"time_limit": REFERENCE_TIME_LIMIT, **(dict(entry.reference_options) if strict else {})})):
        started = time.perf_counter()
        try:
            result = solve(entry.suite, entry.name, path, method=method, **options)
            result["verification"] = verify(entry.suite, entry.name, path, result["output"])
        except Exception as exc:  # e.g. a MIP that cannot prove optimality within its limit
            result = {"best_objective": None, "error": f"{type(exc).__name__}: {exc}"}
        if entry.meta_layout == "recipe_fields":
            result["wall_seconds"] = time.perf_counter() - started
        results[method] = result
    return results


def _verified(result: dict[str, Any]) -> bool:
    return not result.get("error") and bool((result.get("verification") or {}).get("ok"))


def admission_issue(entry: Family, mono: dict[str, Any], ref: dict[str, Any]) -> tuple[str | None, float | None]:
    """The strict rule: (None, gap) for an admitted instance, else (reason, gap)."""
    tol = entry.tol
    if not _verified(mono):
        return f"monolithic MIP not proved optimal or not verified: {mono.get('error') or mono.get('verification')}", None
    truth = float(mono["best_objective"])
    scale = max(1.0, abs(truth))
    seconds = mono.get("total_time", mono.get("runtime"))  # not every MIP wrapper reports its solve time
    if seconds is not None and not float(seconds) <= entry.mip_time_limit:
        return f"MIP time {seconds} s above {entry.mip_time_limit} s", None
    lb, ub = mono.get("global_lb"), mono.get("global_ub")
    if not (isinstance(lb, (int, float)) and isinstance(ub, (int, float)) and abs(ub - lb) <= MIP_BOUND_TOL * scale):
        return f"MIP bound not closed: lb {lb}, ub {ub}", None
    if not _verified(ref):
        return f"decomposition reference failed or not verified: {ref.get('error') or ref.get('verification')}", None
    if not 0.0 <= float(ref.get("total_time", math.inf)) <= REFERENCE_TIME_LIMIT:
        return f"reference time {ref.get('total_time')} s outside [0, {REFERENCE_TIME_LIMIT}] s", None
    value = float(ref["best_objective"])
    gap = (value - truth) / scale
    if not math.isfinite(gap) or gap < -tol or gap > GAP_RULE:
        return f"decomposition gap {gap} outside [{-tol}, {GAP_RULE}]", gap
    matches = abs(value - truth) <= tol * scale
    if entry.reference_certified and not (certified(ref, tol) and matches):
        return "requires a proved, verified MIP optimum and a matching certified reference", gap
    if certified(ref, tol) and not matches:
        return f"certified reference {value} differs from the MIP optimum {truth}", gap
    return None, gap


def _meta_instance_info(entry, inst_dir, seed, size, folder, data, recipe, mono, ref, gap):
    sidecar = _sidecar(inst_dir)
    return {"seed": seed, "size": size, "folder": folder, "m": data.get("m"), "n": data.get("n"),
            "ground_truth_objective": float(mono["best_objective"]), "ground_truth_source": "monolithic_mip",
            "mip_seconds": mono.get("total_time"), "mip_params": {**MIP_PARAMS, "TimeLimit": entry.mip_time_limit},
            "mip_seconds_definition": MIP_SECONDS_DEFINITION, "reference_objective": float(ref["best_objective"]), "reference_gap": gap,
            "reference_seconds": ref.get("total_time"), "reference_proved": bool(ref.get("proven_optimal")),
            "reference_termination": ref.get("termination_reason"),
            "instance_info": sidecar[1] if sidecar else None}


def _meta_recipe_fields(entry, inst_dir, seed, size, folder, data, recipe, mono, ref, gap):
    return {"seed": seed, "size": size, "folder": folder, "ground_truth_objective": float(mono["best_objective"]),
            "ground_truth_source": "monolithic_mip", "mip_time_limit": entry.mip_time_limit, "mip_threads": MIP_PARAMS["Threads"],
            "mip_gap": MIP_PARAMS["MIPGap"], "mip_seconds": mono.get("total_time", mono.get("runtime")), "mip_bound": mono.get("global_lb"),
            "reference_objective": float(ref["best_objective"]), "reference_gap": gap,
            "reference_bound": ref.get("global_lb"), "reference_seconds": ref.get("total_time"), **(recipe or {})}


def _meta_source_summary(entry, inst_dir, seed, size, folder, data, recipe, mono, ref, gap, truth=None, source="monolithic_mip"):
    meta = {"seed": seed, "size": size, "folder": folder, "ground_truth_objective": mono["best_objective"] if truth is None else truth,
            "ground_truth_source": source, "reference_proved": certified(ref, entry.tol), "reference_seconds": (ref or {}).get("total_time"),
            "mip_time_limit": entry.mip_time_limit}
    # Generator provenance (the sidecar; never shown to the agent) is summarized in meta.json. Fully synthetic
    # recipes without a sidecar record the scalar fields of data.json instead.
    sidecar = _sidecar(inst_dir)
    if sidecar:
        meta["source"] = {"file": sidecar[0], **{k: v for k, v in sidecar[1].items() if not isinstance(v, (list, dict))}}
    else:
        meta["source"] = {"synthetic": True, **{k: v for k, v in data.items() if not isinstance(v, (list, dict))}}
    return meta


META_LAYOUTS = {"instance_info": _meta_instance_info, "recipe_fields": _meta_recipe_fields, "source_summary": _meta_source_summary}


def _admit_mip_or_certificate(entry, inst_dir, seed, size, folder, data, results):
    """The historical rule of the reused lbbd, gcol and nrp instances: (meta or None) without raising for a missing optimum."""
    gold = {method: (result if _verified(result) else None) for method, result in results.items()}
    mono, ref = gold["monolithic"], gold["decomposition"]
    tol = entry.tol
    if mono is not None and ref is not None and certified(ref, tol) and abs(mono["best_objective"] - ref["best_objective"]) > tol * max(1.0, abs(mono["best_objective"])):
        raise RuntimeError(f"{folder}: certified reference {ref['best_objective']} differs from the MIP optimum {mono['best_objective']}")
    if mono is not None and isinstance(mono.get("best_objective"), (int, float)) and math.isfinite(mono["best_objective"]):
        truth, source = mono["best_objective"], "monolithic_mip"
    elif ref is not None and certified(ref, tol):
        truth, source = ref["best_objective"], "decomposition_certificate"
    else:
        return None
    return _meta_source_summary(entry, inst_dir, seed, size, folder, data, None, mono or {}, ref, None, truth=truth, source=source)


def generate_suite(problem: str, *, sizes, num_instances: int, out_root: str | Path, seed_offset: int = 0,
                   gen: Callable | None = None, render_prompt: Callable[[dict], str] | None = None,
                   contract: str | None = None) -> list[dict[str, Any]]:
    """Generate, solve, verify and admit the instances of one registered family (see the module docstring).

    gen(seed, size, inst_dir) must write data.json (and any sidecar) and return the payload, or (payload, recipe
    fields); it defaults to the family's registered generator. render_prompt defaults to the family's template under
    `contract` (default: the contract of the family's dataset)."""
    entry = family(problem)
    if entry.admission not in {"strict", "mip_or_certificate"}:
        raise ValueError(f"{problem} is generated by its own pipeline (src/{entry.suite}/{problem}/c_gen.py)")
    strict = entry.admission == "strict"
    gen = gen or _generator(entry)
    render = render_prompt or _render(entry, contract)
    out_root = Path(out_root)
    metas = []
    for size in sizes:
        for seed in range(seed_offset, seed_offset + num_instances):
            folder = f"{problem}_{size}_seed{seed:03d}"
            inst_dir = out_root / folder
            inst_dir.mkdir(parents=True, exist_ok=True)
            # Old results must never survive a regeneration; meta.json is published again only after admission.
            for stale in ("meta.json", "rejection.json", "gold_monolithic.json", f"gold_{entry.suite}.json", "prompt.txt", *SIDECARS):
                (inst_dir / stale).unlink(missing_ok=True)
            try:
                generated = gen(seed, size, inst_dir)
                data, recipe = generated if isinstance(generated, tuple) else (generated, None)
                (inst_dir / "prompt.txt").write_text(render(data).rstrip() + "\n")
            except Exception as exc:
                _write(inst_dir / "rejection.json", {"folder": folder, "reason": f"generation or prompt failed: {type(exc).__name__}: {exc}"})
                raise RuntimeError(f"{folder}: rejected: generation or prompt failed") from exc
            path = inst_dir / "data.json"
            results = _references(entry, path, strict=strict)
            for method, filename in (("monolithic", "gold_monolithic.json"), ("decomposition", f"gold_{entry.suite}.json")):
                _write(inst_dir / filename, results[method])
            if strict:
                reason, gap = admission_issue(entry, results["monolithic"], results["decomposition"])
                if reason is not None:
                    _write(inst_dir / "rejection.json", {"folder": folder, "reason": reason})
                    raise RuntimeError(f"{folder}: rejected: {reason}")
                meta = META_LAYOUTS[entry.meta_layout](entry, inst_dir, seed, size, folder, data, recipe, results["monolithic"], results["decomposition"], gap)
            else:
                meta = _admit_mip_or_certificate(entry, inst_dir, seed, size, folder, data, results)
                if meta is None:
                    continue
            _write(inst_dir / "meta.json", meta)
            metas.append(meta)
            print(json.dumps({k: meta.get(k) for k in ("folder", "ground_truth_objective", "ground_truth_source", "reference_seconds")}), flush=True)
    return metas
